import{_ as f,C as s,o as i,c as n,a3 as t,E as r,j as a,a as o}from"./chunks/framework.1Rq3Io9y.js";const A=JSON.parse('{"title":"Séance 8 — Estimer le temps et monter le devis","description":"","frontmatter":{"title":"Séance 8 — Estimer le temps et monter le devis","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/08-estimer-et-chiffrer.md","filePath":"modules/01-faisabilite/08-estimer-et-chiffrer.md"}'),v={name:"modules/01-faisabilite/08-estimer-et-chiffrer.md"},x={style:{"overflow-x":"auto"}},q={class:"schema-exemple",style:{"min-width":"540px",display:"block"},viewBox:"0 0 700 230",role:"img","aria-label":"Schéma : le site envoie la commande à l'outil de commande, qui envoie le paiement au terminal et le courriel de confirmation au client. La liste de production est imprimée à la main."};function _(T,e,y,L,C,P){const l=s("FilDeLaSeance"),u=s("FigurePoids"),d=s("FigureOublis"),c=s("FigureTroisChiffres"),p=s("EstimationTroisChiffres"),g=s("FigureEcheancier"),m=s("FigureDevis"),h=s("FigureTroisFacons"),b=s("EntrerDansLeBudget");return i(),n("div",null,[e[1]||(e[1]=t('<h1 id="seance-8-—-estimer-le-temps-et-monter-le-devis" tabindex="-1">Séance 8 — Estimer le temps et monter le devis <a class="header-anchor" href="#seance-8-—-estimer-le-temps-et-monter-le-devis" aria-label="Permalink to &quot;Séance 8 — Estimer le temps et monter le devis&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li><strong>Choisir</strong> un outil avec des critères pondérés.</li><li><strong>Estimer</strong> le travail en trois chiffres et le placer dans un <strong>échéancier</strong> avec un coussin.</li><li>Monter un <strong>devis</strong> sur trois ans et proposer <strong>trois façons d&#39;entrer dans le budget</strong>.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><p>La matière d&#39;abord, en grand groupe, puis le <strong>Lab 08</strong> en équipe jusqu&#39;à la fin de la soirée.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Retour sur le Lab 07</td></tr><tr><td style="text-align:left;">18 h 45</td><td style="text-align:left;">Vos questions sur l&#39;évaluation 2</td></tr><tr><td style="text-align:left;">18 h 55</td><td style="text-align:left;">La mise en situation et le plan de la soirée</td></tr><tr><td style="text-align:left;">19 h 00</td><td style="text-align:left;">Étape 1 — Choisir avec des critères</td></tr><tr><td style="text-align:left;">19 h 05</td><td style="text-align:left;">Étape 2 — Estimer le travail</td></tr><tr><td style="text-align:left;">19 h 15</td><td style="text-align:left;">Activité 1 — L&#39;estimation de la boulangerie</td></tr><tr><td style="text-align:left;">19 h 35</td><td style="text-align:left;">Étape 3 — Placer le travail dans le temps</td></tr><tr><td style="text-align:left;">19 h 45</td><td style="text-align:left;">Étape 4 — Chiffrer et entrer dans le budget</td></tr><tr><td style="text-align:left;">19 h 55</td><td style="text-align:left;">Activité 2 — Faire entrer la boulangerie dans le budget</td></tr><tr><td style="text-align:left;">20 h 15</td><td style="text-align:left;">La suite du cours · consignes du Lab 08 et à faire à la maison</td></tr><tr><td style="text-align:left;">20 h 25</td><td style="text-align:left;">Marge pour les questions</td></tr><tr><td style="text-align:left;">20 h 35</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 50</td><td style="text-align:left;"><a href="./../../labs/lab08-estimer-et-chiffrer">Lab 08 — Estimer et chiffrer la proposition</a>, jusqu&#39;à la fin de la soirée</td></tr></tbody></table><p>Le <strong>retour sur le Lab 08</strong> aura lieu au début de la séance 9.</p><hr><h2 id="retour-lab-07" tabindex="-1">Retour sur le Lab 07 <a class="header-anchor" href="#retour-lab-07" aria-label="Permalink to &quot;Retour sur le Lab 07 {#retour-lab-07}&quot;">​</a></h2><p>Dans le chat : <strong>le fichier qui vous a donné le plus de mal</strong>, et ce que vous avez fait.</p><h2 id="vos-questions-sur-l-evaluation-2" tabindex="-1">Vos questions sur l&#39;évaluation 2 <a class="header-anchor" href="#vos-questions-sur-l-evaluation-2" aria-label="Permalink to &quot;Vos questions sur l&#39;évaluation 2&quot;">​</a></h2><p>Dans le chat, maintenant, pour tout le groupe.</p><hr><h2 id="mise-en-situation" tabindex="-1">La mise en situation et le plan de la soirée <a class="header-anchor" href="#mise-en-situation" aria-label="Permalink to &quot;La mise en situation et le plan de la soirée {#mise-en-situation}&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Mise en situation, inventée pour le cours : la boulangerie</strong><br> Ce soir, on ne travaille pas sur Aventure Saint-Maurice. On s&#39;exerce sur un <strong>petit projet inventé</strong>, plus simple, pour voir chaque méthode une fois au complet. Les outils de la boulangerie sont inventés aussi. <ul class="list-disc pl-5"><li>Une boulangerie de quartier veut que ses clients <strong>commandent en ligne pour le samedi</strong>.</li><li>Le menu <strong>change chaque semaine</strong> et la propriétaire veut le changer seule.</li><li>Elle garde son <strong>terminal de paiement</strong> actuel.</li><li>Budget de construction : <strong>6 000 $</strong>. Mise en ligne voulue : le <strong>1<sup>er</sup> décembre</strong>.</li></ul> Ensuite, dans le Lab 08, vous refaites les mêmes étapes pour <strong>Aventure Saint-Maurice</strong>. </div>',15)),r(l),e[2]||(e[2]=t('<p>Chaque étape est présentée de la même façon : <strong>la question</strong>, <strong>la méthode</strong> en quelques gestes, <strong>l&#39;exemple</strong> de la boulangerie, puis <strong>à retenir</strong> et <strong>où ça va</strong> dans votre rapport.</p><hr><h2 id="choisir-avec-des-criteres" tabindex="-1">Étape 1 sur 4 — Choisir avec des critères <a class="header-anchor" href="#choisir-avec-des-criteres" aria-label="Permalink to &quot;Étape 1 sur 4 — Choisir avec des critères {#choisir-avec-des-criteres}&quot;">​</a></h2><p><strong>La question.</strong> Plusieurs outils font l&#39;affaire. Lequel prendre, et comment le justifier au client ?</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Écrire les critères.</strong> Chaque critère vient d&#39;une exigence ou d&#39;une contrainte déjà écrite dans le rapport. On n&#39;en invente pas.</li><li><strong>Donner un poids à chacun.</strong> 3 = indispensable, 2 = important, 1 = souhaitable.</li><li><strong>Trier les outils, du poids le plus fort au plus faible.</strong> Un outil qui échoue à un critère de poids 3 est écarté.</li></ol><p><strong>Dans la boulangerie.</strong> Les critères, et d&#39;où ils viennent :</p><table><thead><tr><th>Critère</th><th>D&#39;où il vient</th><th>Poids</th></tr></thead><tbody><tr><td>La propriétaire change le menu seule, chaque vendredi</td><td>Exigence : « le menu change toutes les semaines »</td><td>3</td></tr><tr><td>Le paiement passe par son terminal actuel</td><td>Contrainte technologique : elle garde son terminal</td><td>2</td></tr><tr><td>Moins de 40 $ par mois</td><td>Contrainte de budget</td><td>2</td></tr><tr><td>Un rappel par texto la veille</td><td>Exigence souhaitée : « les clients oublient »</td><td>1</td></tr></tbody></table><p>Puis le tri, de gauche à droite :</p>',9)),r(u),e[3]||(e[3]=a("p",null,"Une fois les outils choisis, un schéma montre ce qui passe de l'un à l'autre :",-1)),a("div",x,[(i(),n("svg",q,[...e[0]||(e[0]=[t('<defs><marker id="fl" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="currentColor"></path></marker></defs><g fill="none" stroke="currentColor" stroke-width="1.5"><rect x="5" y="20" width="170" height="50" rx="8"></rect><rect x="265" y="20" width="170" height="50" rx="8"></rect><rect x="525" y="20" width="170" height="50" rx="8"></rect><rect x="265" y="170" width="170" height="50" rx="8"></rect><rect x="525" y="170" width="170" height="50" rx="8"></rect><path d="M175,45 H261" marker-end="url(#fl)"></path><path d="M435,45 H521" marker-end="url(#fl)"></path><path d="M435,66 L560,166" marker-end="url(#fl)"></path><path d="M350,70 V166" stroke-dasharray="6 5" marker-end="url(#fl)"></path></g><g fill="currentColor" font-size="14" text-anchor="middle"><text x="90" y="50">Site de la boulangerie</text><text x="350" y="50">Outil de commande</text><text x="610" y="50">Terminal de paiement</text><text x="350" y="200">Liste de production</text><text x="610" y="200">Client</text><g font-size="12"><text x="218" y="36">la commande</text><text x="478" y="36">le paiement</text><text x="508" y="112" text-anchor="start">courriel de</text><text x="508" y="127" text-anchor="start">confirmation</text><text x="340" y="112" text-anchor="end">imprimée à la main,</text><text x="340" y="127" text-anchor="end">le vendredi soir</text></g></g>',3)])]))]),e[4]||(e[4]=t('<p>Une boîte par outil, une flèche par chose qui passe d&#39;un outil à l&#39;autre, nommée sur la flèche. La flèche en pointillé est une <strong>manipulation à la main</strong> : quelqu&#39;un devra la faire chaque semaine.</p><div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> On ne choisit pas l&#39;outil « le meilleur » : on choisit celui qui passe les critères de poids 3, puis le meilleur sur les critères de poids 2.<br><strong>Où ça va.</strong> Évaluation 2, sections 8.1 (les critères), 8.2 (les choix) et 8.3 (le schéma). À faire à la maison, avec les <a href="./../../fiches/eval2-tableaux-communs.docx" download>tableaux de comparaison communs</a>. Ce n&#39;est pas dans le Lab 08. </div><hr><h2 id="estimer-le-travail" tabindex="-1">Étape 2 sur 4 — Estimer le travail <a class="header-anchor" href="#estimer-le-travail" aria-label="Permalink to &quot;Étape 2 sur 4 — Estimer le travail {#estimer-le-travail}&quot;">​</a></h2><p><strong>La question.</strong> Combien d&#39;heures le studio va-t-il travailler ? À 75 $ de l&#39;heure, une heure oubliée est une heure payée par le studio, ou une fonctionnalité non livrée.</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Découper en tâches.</strong> Une tâche : une personne, une ou deux journées au plus. « Faire le site » n&#39;est pas une tâche. Puis relire la liste des cinq tâches qu&#39;on oublie :</li></ol>',7)),r(d),e[5]||(e[5]=t('<ol start="2"><li><p><strong>Donner trois chiffres par tâche, et en tirer un.</strong> Un seul chiffre, c&#39;est presque toujours le plus optimiste : on imagine la tâche qui se passe bien. Trois chiffres obligent à penser aussi à ce qui peut mal tourner.</p><p><strong>Comment trouver les trois chiffres, dans cet ordre :</strong></p><ul><li><strong>Le probable d&#39;abord.</strong> Pensez à la dernière fois que vous avez fait une tâche semblable, dans un lab ou un projet : combien de temps ça a vraiment pris ? Si vous ne l&#39;avez jamais faite, essayez-en un petit bout pendant 15 minutes, ou demandez à quelqu&#39;un qui l&#39;a déjà faite.</li><li><strong>L&#39;optimiste ensuite.</strong> Reprenez le probable et enlevez les embûches : rien à chercher, tout marche du premier coup. Il est plus petit que le probable, souvent de la moitié aux trois quarts.</li><li><strong>Le pessimiste à la fin.</strong> Écrivez ce qui peut mal tourner (un outil qu&#39;on ne connaît pas, le soutien à contacter, un texte du client en retard, un bogue) et ajoutez au probable le temps que chaque problème ferait perdre. On compte ce qui arrive vraiment de temps en temps, pas la catastrophe.</li></ul><p><strong>Puis on en tire un seul chiffre, l&#39;estimation retenue</strong>, celui qu&#39;on met au devis. On ne prend pas simplement le probable, parce qu&#39;il oublie les mauvais jours. On ne prend pas le pessimiste non plus, parce que le devis serait trop cher.</p><p><strong>D&#39;où vient le « 4 × » :</strong> imaginez que vous faites la même tâche six fois. Une fois, tout va bien (l&#39;optimiste). Une fois, ça tourne mal (le pessimiste). Les quatre autres fois, ça se passe comme d&#39;habitude (le probable, quatre fois). L&#39;estimation retenue est la moyenne de ces six fois : on additionne les six chiffres, puis on divise par 6.</p><p>Pour relier la réservation à Square : 2 + (4 + 4 + 4 + 4) + 10 = 28 heures pour six fois, donc 28 ÷ 6 ≈ <strong>4,7 h</strong> par fois. C&#39;est la méthode PERT, utilisée en gestion de projet. La fiche du Lab fait le calcul pour vous.</p></li></ol>',1)),r(c),e[6]||(e[6]=t('<ol start="3"><li><strong>Comparer à un projet semblable.</strong> Si un site semblable a pris 90 heures et que votre total en donne 45, il manque des tâches.</li></ol><div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> Une tâche avec un grand écart entre l&#39;optimiste et le pessimiste est un risque : on l&#39;essaie en premier.<br><strong>Où ça va.</strong> Évaluation 2, section 11.1. Lab 08, partie 1. </div><h3 id="activite-1" tabindex="-1">Activité 1 — L&#39;estimation de la boulangerie <a class="header-anchor" href="#activite-1" aria-label="Permalink to &quot;Activité 1 — L&#39;estimation de la boulangerie {#activite-1}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min en équipe, puis 10 min de retour en grand groupe)</strong><br> Une collègue pressée a estimé le site de la boulangerie avec un seul chiffre par tâche : le probable. <ol class="list-decimal pl-5"><li><strong>Pour chaque tâche</strong>, écrivez l&#39;<strong>optimiste</strong> (plus petit que le probable), puis le <strong>pessimiste</strong> (plus grand). L&#39;estimation retenue se calcule seule.</li><li><strong>Cochez les tâches oubliées</strong> dans la deuxième liste. Aidez-vous des cinq tâches qu&#39;on oublie, plus haut.</li><li><strong>Cliquez sur « Comparer avec le projet semblable »</strong> et regardez l&#39;écart.</li><li><strong>Copiez vos réponses</strong> avec le bouton, pour les garder.</li></ol><strong>Si vous bloquez</strong> sur un chiffre : imaginez la tâche qui se passe bien (optimiste), puis la même tâche un mauvais jour (pessimiste). Un chiffre raisonnable suffit; il n&#39;y a pas de réponse exacte.<br><strong>Pour le retour en groupe :</strong> quelle tâche a le plus grand écart, et pourquoi ? </div>',4)),r(p),e[7]||(e[7]=t('<hr><h2 id="echeancier" tabindex="-1">Étape 3 sur 4 — Placer le travail dans le temps <a class="header-anchor" href="#echeancier" aria-label="Permalink to &quot;Étape 3 sur 4 — Placer le travail dans le temps {#echeancier}&quot;">​</a></h2><p><strong>La question.</strong> Le travail estimé sera-t-il fini à la date voulue ?</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Partir de la date qu&#39;on ne peut pas déplacer</strong>, et remonter vers aujourd&#39;hui.</li><li><strong>Regrouper les tâches en 4 à 6 étapes</strong> (démarrage, maquettes, construction, tests et formation…), puis ajouter un <strong>coussin</strong> : une étape à part, de 15 à 20 % de la durée.</li><li><strong>Dater tout ce que le client doit fournir</strong> : l&#39;accès au domaine, ses commentaires, ses textes et ses photos.</li></ol><p><strong>Dans la boulangerie</strong>, mise en ligne le 1<sup>er</sup> décembre :</p>',6)),r(g),e[8]||(e[8]=t('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> Un texte du client en retard est la première cause de retard d&#39;un petit projet : sa date est dans l&#39;échéancier.<br><strong>Pour Aventure Saint-Maurice :</strong> la date ferme est le <strong>1<sup>er</sup> mars 2027</strong>. Pensez aux fêtes, et à la réponse de la MRC en <strong>janvier</strong> : qu&#39;est-ce qui en dépend ?<br><strong>Où ça va.</strong> Évaluation 2, section 11.2. Lab 08, partie 2. </div><hr><h2 id="devis" tabindex="-1">Étape 4 sur 4 — Chiffrer et entrer dans le budget <a class="header-anchor" href="#devis" aria-label="Permalink to &quot;Étape 4 sur 4 — Chiffrer et entrer dans le budget {#devis}&quot;">​</a></h2><p><strong>La question.</strong> Combien le projet coûte-t-il, et est-ce que ça entre dans le budget ?</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Les coûts uniques</strong> : les heures retenues × 75 $, plus ce qui s&#39;achète une fois. On les compare au <strong>budget de construction</strong>.</li><li><strong>Les coûts annuels</strong> : les abonnements, les commissions, le domaine. On les compare à <strong>ce que le client paie aujourd&#39;hui</strong>.</li><li><strong>Si ça dépasse</strong>, on ne baisse pas les heures : on propose <strong>trois façons d&#39;entrer dans le budget</strong>, et le client choisit.</li></ol><p><strong>Dans la boulangerie</strong>, le devis se lit en trois comparaisons :</p>',7)),r(m),e[9]||(e[9]=a("p",null,[o("Une commission se calcule avec le "),a("strong",null,"volume"),o(". Pour Aventure Saint-Maurice : 2 600 réservations × montant moyen × pourcentage. Écrivez le calcul sous le tableau.")],-1)),e[10]||(e[10]=a("p",null,"Quand le devis dépasse, trois familles de solutions :",-1)),r(h),e[11]||(e[11]=t('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> Chaque option dit ce qu&#39;elle fait économiser <strong>et ce que le client perd</strong>. Les tests, la formation et l&#39;accessibilité ne se coupent jamais.<br><strong>Où ça va.</strong> Évaluation 2, section 12. Lab 08, parties 3 et 4. </div><h3 id="activite-2" tabindex="-1">Activité 2 — Faire entrer la boulangerie dans le budget <a class="header-anchor" href="#activite-2" aria-label="Permalink to &quot;Activité 2 — Faire entrer la boulangerie dans le budget {#activite-2}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min en équipe, puis 10 min de retour en grand groupe)</strong><br> Le devis de la boulangerie dépasse son budget de 6 000 $. Six mesures sont proposées. <ol class="list-decimal pl-5"><li><strong>Pour chaque mesure</strong>, écrivez en une phrase <strong>ce que la cliente perd</strong>.</li><li>Choisissez <strong>Proposer</strong> ou <strong>Écarter</strong>.</li><li><strong>Cliquez sur « Vérifier »</strong> pour voir l&#39;effet sur trois ans, puis lisez l&#39;explication des mesures où vous vous êtes trompés.</li><li><strong>Copiez vos réponses</strong> avec le bouton, pour les garder.</li></ol><strong>Si vous bloquez :</strong> relisez le tableau des critères de la boulangerie (étape 1). Une mesure qui fait échouer un critère de poids 3 s&#39;écarte.<br><strong>Pour le retour en groupe :</strong> quelle mesure avait l&#39;air bonne, mais ne l&#39;était pas sur trois ans ? </div>',3)),r(b),e[12]||(e[12]=t('<hr><h2 id="la-suite" tabindex="-1">La suite du cours et la rencontre avec le client <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La suite du cours et la rencontre avec le client {#la-suite}&quot;">​</a></h2><p>On passe de <strong>HK29</strong> (la faisabilité) à <strong>HK33</strong> (la conception) : ce que la proposition décide sera construit dans la deuxième partie du cours. Le mode agile viendra aux séances 16 et 17.</p><p>La <strong>séance 9 (25 novembre)</strong> est une <strong>rencontre avec Mélanie</strong>. Apportez <strong>dix questions</strong>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">✕ À éviter</th><th style="text-align:left;">✓ À poser</th></tr></thead><tbody><tr><td style="text-align:left;">« Est-ce que vous aimez le bleu ? »</td><td style="text-align:left;">« Quelle politique d&#39;annulation voulez-vous ? » : <strong>une question, une décision</strong></td></tr><tr><td style="text-align:left;">« Avez-vous besoin d&#39;un mode hors ligne ? »</td><td style="text-align:left;">« Les guides doivent-ils voir la liste au quai, sans réseau ? » : <strong>dans ses mots à elle</strong></td></tr></tbody></table><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab08-estimer-et-chiffrer">Lab 08 — Estimer et chiffrer la proposition</a>, en équipe. Gardez votre rapport de l&#39;évaluation 1 sous la main. Le lab reprend les étapes 2, 3 et 4, dans le même ordre.</p><hr><h2 id="a-faire-a-la-maison" tabindex="-1">À faire à la maison <a class="header-anchor" href="#a-faire-a-la-maison" aria-label="Permalink to &quot;À faire à la maison {#a-faire-a-la-maison}&quot;">​</a></h2><ul><li><strong>Terminer le Lab 08</strong> : la fiche devient vos sections 11 et 12.</li><li><strong>Écrire vos choix (section 8.2)</strong> à partir de vos critères (section 8.1). N&#39;attendez pas la rencontre.</li><li><strong>Préparer vos dix questions</strong> pour Mélanie et les déposer dans l&#39;équipe Teams avant la séance 9.</li></ul><hr><h2 id="avant-la-seance-9-25-novembre" tabindex="-1">Avant la séance 9 (25 novembre) <a class="header-anchor" href="#avant-la-seance-9-25-novembre" aria-label="Permalink to &quot;Avant la séance 9 (25 novembre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Copier vos réponses des activités 1 et 2 dans vos notes</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer la fiche du Lab 08 dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer vos dix questions pour Mélanie au même endroit</span></label></li><li><label><input type="checkbox"><span class="check-text">Avoir un premier jet de la section 8.2 pour les cinq questions</span></label></li></ul>',14))])}const k=f(v,[["render",_]]);export{A as __pageData,k as default};
